INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Anpassen der Projektplanung Teil der Durchführung?', 2, '[{"text": "Ja", "correct": true, "because": "Reagiert auf Abweichungen"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Durchführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Anpassen der Projektplanung?', 3, '[{"text": "Projekt auf Kurs halten", "correct": true, "because": "Korrigiert Abweichungen"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Planungsaspekt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anpassungen reagieren auf Ist-Zustand. b) Sie erfolgen nur in der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Durchführung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe führen zur Anpassung der Projektplanung?', 4, '[{"text": "Zeitverzögerungen", "correct": true, "because": "Beeinflussen Ablauf"}, {"text": "Unklare Ziele", "correct": false, "because": "Planungsproblem"}, {"text": "Ressourcenmangel", "correct": true, "because": "Verändern Verfügbarkeit"}, {"text": "Änderungswünsche", "correct": true, "because": "Kundenanforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Durchführung ohne Anpassungen der Planung ablaufen?', 2, '[{"text": "Nein", "correct": true, "because": "Abweichungen üblich"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft beim Anpassen der Projektplanung?', 3, '[{"text": "Gantt-Diagramm", "correct": true, "because": "Zeigt Zeitverschiebungen"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Anpassen der Projektplanung nur bei großen Projekten nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte ändern sich"}, {"text": "Ja", "correct": false, "because": "Breite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt wird beim Anpassen der Projektplanung überprüft?', 3, '[{"text": "Aktueller Projektfortschritt", "correct": true, "because": "Basis für Anpassung"}, {"text": "Teamzufriedenheit", "correct": false, "because": "Nebenaspekt"}, {"text": "Kostenübersicht allein", "correct": false, "because": "Teilweise relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anpassungen basieren auf Controlling. b) Sie sind immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Änderungen üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Anpassung der Projektplanung?', 3, '[{"text": "Projektziele gefährdet", "correct": true, "because": "Abweichungen unkontrolliert"}, {"text": "Durchführung wird effizienter", "correct": false, "because": "Eher Chaos"}, {"text": "Kosten sinken", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Projektplanung ohne Controlling angepasst werden?', 2, '[{"text": "Nein", "correct": true, "because": "Datenbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Uninformierte Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Anpassung der Projektplanung?', 3, '[{"text": "Zeitplan um 2 Wochen verlängern", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas ändern", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Keine Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Anpassen der Planung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team muss informiert sein"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente werden beim Anpassen der Planung betrachtet?', 4, '[{"text": "Zeitplan", "correct": true, "because": "Korrigiert Termine"}, {"text": "Unklare Daten", "correct": false, "because": "Erschweren Anpassung"}, {"text": "Ressourcen", "correct": true, "because": "Beeinflussen Verfügbarkeit"}, {"text": "Arbeitspakete", "correct": true, "because": "Passen Aufgaben an"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Anpassen der Planung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Anpassen der Projektplanung?', 3, '[{"text": "Flexibilität im Projekt sichern", "correct": true, "because": "Reagiert auf Änderungen"}, {"text": "Neue Ziele definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Technische Lösung finden", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Planung ohne Stakeholder-Abstimmung angepasst werden?', 2, '[{"text": "Nein", "correct": true, "because": "Einvernehmen nötig"}, {"text": "Ja", "correct": false, "because": "Risiko von Konflikten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erfordert eine Anpassung der Planung?', 3, '[{"text": "Verzögerung bei Lieferanten", "correct": true, "because": "Beeinflusst Zeitplan"}, {"text": "Klarer Fortschritt", "correct": false, "because": "Keine Anpassung nötig"}, {"text": "Gute Teamarbeit", "correct": false, "because": "Fördert Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anpassungen korrigieren Abweichungen. b) Sie sind nur für Zeitpläne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Anpassens der Projektplanung?', 3, '[{"text": "Erfolg trotz Änderungen sichern", "correct": true, "because": "Hält Projekt am Ziel"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Flexibilität", "correct": false, "because": "Fördert Anpassung"}]');
